astral-crlf:
{% set r = "lr1" %}
SET {{ r }} cr0;;
# 😀 x
B 😀x;;

astral-label:
# 😀😀 HALT
top: SET lr0 cr0;; # 😀
    BLT.S lr0 cr4 top;;

macro-param:
{% set r = "lr0" %}
{% macro m(r) %}
SET {{ r }} cr0;;
{% endmacro %}
{{ m("lr2") }}
SET {{ r }} cr1;;

loop:
{% set r = "lr0" %}
{% for i in range(2) %}
SET {{ r }} cr0;;
{% endfor %}
HALT;;

hints-unused:
{% set r = "lr0" %}
{% set n = 3 %}
SET {{ r }} cr0;;
end:
    HALT;;

kwarg:
{% macro m(dest, n=1) %}
SET {{ dest }} cr{{ n }};;
{% endmacro %}
{% set n = 2 %}
{{ m(dest="lr1", n=n) }}

header:
{#- ipu:params
rows: int = 4    # rows to copy
-#}
{% set r = "lr0" %}
SET {{ r }} cr0;;
{% for i in range(rows) %}
HALT;;
{% endfor %}

labels:
top:
    SET lr0 cr0;;
    BLT.S lr0 cr4 top;;
    B +1;;
end: HALT;;

dict-kwarg:
{% macro m(x) %}
SET {{ x }} cr0;;
{% endmacro %}
{% set d = dict(x="lr1") %}
{{ m(x=d.x) }}

filter-name:
{% set length = 2 %}
{% set xs = [1] %}
SET lr0 cr{{ length + (xs | length) }};;
